using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
class VoicePanel:StackPanel {
 public Action OpenCandidates;readonly Slider volume=new Slider();readonly TextBlock level=new TextBlock{VerticalAlignment=VerticalAlignment.Center};bool syncingVolume;readonly CheckBox ambientToggle;readonly VoiceRuntime voice;readonly TextBlock status=new TextBlock{TextWrapping=TextWrapping.Wrap},details=new TextBlock{TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,12,0,12)};readonly ListBox clips=new ListBox{Height=270};
 public VoicePanel(VoiceRuntime runtime){voice=runtime;Margin=new Thickness(20);Children.Add(new TextBlock{Text="柯南 · 日语原声",FontSize=25,Margin=new Thickness(0,0,0,12)});Children.Add(new TextBlock{Text="来源：101Soundboards上的Puyo Puyo!! Quest联动角色录音，共29段。踢球、推理、夸奖支持自主互动配音，下班倒计时使用对应数字，其余录音保留试听。",TextWrapping=TextWrapping.Wrap});
  Toggle("启用原声配音",voice.Settings.Enabled,value=>voice.Settings.Enabled=value);Toggle("点击与动作配音",voice.Settings.Interactions,value=>voice.Settings.Interactions=value);ambientToggle=Toggle("待机与漫游语音",voice.Settings.Ambient,value=>voice.Settings.Ambient=value);Toggle("搜索、待办与专注等工作反馈",voice.Settings.Workflows,value=>voice.Settings.Workflows=value);Toggle("到期提醒短声（上吧，默认关闭）",voice.Settings.Reminders,value=>voice.Settings.Reminders=value);
  var candidatesButton=new Button{Content="新下载的原声候选 · "+voice.Candidates.Clips.Count+" 段",HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,10,0,10)};candidatesButton.Click+=(s,e)=>{if(OpenCandidates!=null)OpenCandidates();};Children.Add(candidatesButton);
  Toggle("点击语音直接试听",voice.Settings.ClickToPreview,value=>voice.Settings.ClickToPreview=value);
  var row=new WrapPanel{Margin=new Thickness(0,10,0,10)};Children.Add(row);row.Children.Add(new TextBlock{Text="音量",VerticalAlignment=VerticalAlignment.Center});volume.Minimum=0;volume.Maximum=100;volume.Value=voice.Settings.Volume*100;volume.Width=220;volume.TickFrequency=5;volume.IsSnapToTickEnabled=true;volume.Margin=new Thickness(12,0,12,0);row.Children.Add(volume);level.Text=volume.Value.ToString("F0")+"%";row.Children.Add(level);volume.ValueChanged+=(s,e)=>{if(syncingVolume)return;voice.SetVolume(volume.Value/100);level.Text=volume.Value.ToString("F0")+"%";Save();};Tool(row,"停止播放",voice.Stop);
  Children.Add(new TextBlock{Text="自动播放间隔至少8秒；同类至少20秒（点击30秒），同一消息120秒不重复。不叠音、不排队补播；自动配音在隐藏、全屏应用时静音。自主互动配音至少间隔45秒，同一动作120秒不重复；系统通知不主动配音。下班倒计时使用对应数字原声；计时提醒可以唤醒。数数使用中文手势：6伸拇指和小指、7三指捏合、8拇指食指张开、9食指弯钩、10握拳；11—19另一手握拳加10，20双拳。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,12)});Children.Add(status);clips.ItemsSource=voice.Catalog.Clips;Children.Add(clips);clips.SelectionChanged+=(s,e)=>{var clip=clips.SelectedItem as VoiceClip;if(clip!=null)details.Text=clip.Japanese+"\n"+clip.Chinese+"\n"+clip.Note+"\n动作："+clip.Action+" · 情绪："+clip.Emotion+(clip.Count>0?" · 数字："+clip.Count:"")+"\n"+clip.Seconds.ToString("F2")+"秒 · "+(clip.Events.Length==0?"仅供手动试听":String.Join(" / ",clip.Events.Select(EventLabel).ToArray()));};clips.PreviewMouseLeftButtonUp+=(s,e)=>{if(!voice.Settings.ClickToPreview)return;var item=ItemsControl.ContainerFromElement(clips,e.OriginalSource as DependencyObject) as ListBoxItem;if(item!=null)voice.Preview(item.Content as VoiceClip);};Children.Add(details);var actions=new WrapPanel();Children.Add(actions);Tool(actions,"试听选中语音",()=>voice.Preview(clips.SelectedItem as VoiceClip));Tool(actions,"打开素材文件夹",()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"voices")){UseShellExecute=true}));voice.Changed+=Refresh;Refresh();if(clips.Items.Count>0)clips.SelectedItem=voice.Catalog.Clips.FirstOrDefault(c=>c.Events.Contains("click"))??voice.Catalog.Clips[0];
 }
 static string EventLabel(string kind){switch(kind){case "click":return "点击角色";case "search-found":return "搜索找到结果";case "task-complete":return "完成待办";case "focus-complete":return "完成一轮专注";case "focus-start":return "开始专注";case "search-error":return "搜索异常";case "reminder":return "到期提醒（需启用）";default:return kind;}}
 CheckBox Toggle(string caption,bool initial,Action<bool> apply){var check=new CheckBox{Content=caption,IsChecked=initial};check.Click+=(s,e)=>{apply(check.IsChecked==true);Save();};Children.Add(check);return check;}
 void Save(){try{voice.Apply();}catch(System.IO.IOException e){MessageBox.Show(e.Message,"原声设置");}catch(UnauthorizedAccessException e){MessageBox.Show(e.Message,"原声设置");}}
 static void Tool(Panel panel,string caption,Action action){var b=new Button{Content=caption,HorizontalAlignment=HorizontalAlignment.Left};b.Click+=(s,e)=>action();panel.Children.Add(b);}
 void Refresh(){ambientToggle.IsChecked=voice.Settings.Ambient;status.Text=voice.Status;syncingVolume=true;try{volume.IsEnabled=voice.Settings.Enabled;volume.Value=voice.Settings.Volume*100;level.Text=volume.Value<=0?"0% · 静音":volume.Value.ToString("F0")+"%";}finally{syncingVolume=false;}}
 public void Detach(){voice.Changed-=Refresh;}
}
